import{_ as i,o as a,c as n,a4 as r}from"./chunks/framework.CzJ_HCFe.js";const u=JSON.parse('{"title":"Appendix II lunar longitudes: research transcription","description":"","frontmatter":{},"headers":[],"relativePath":"research/vakya-1962-lunar-table/README.md","filePath":"research/vakya-1962-lunar-table/README.md","lastUpdated":1789991296000}'),t={name:"research/vakya-1962-lunar-table/README.md"};function s(o,e,l,d,c,p){return a(),n("div",null,[...e[0]||(e[0]=[r('<h1 id="appendix-ii-lunar-longitudes-research-transcription" tabindex="-1">Appendix II lunar longitudes: research transcription <a class="header-anchor" href="#appendix-ii-lunar-longitudes-research-transcription" aria-label="Permalink to &quot;Appendix II lunar longitudes: research transcription&quot;">​</a></h1><p>This is a research-only numeric transcription of all 248 lunar longitude rows. Source: the 1962 scan linked in <code>metadata.json</code>, physical PDF pages 162-171, printed pages 125-134. The opening page&#39;s printed numeral is absent; 125 is inferred from the following printed 126 and the book pagination.</p><h2 id="files" tabindex="-1">Files <a class="header-anchor" href="#files" aria-label="Permalink to &quot;Files&quot;">​</a></h2><ul><li><code>lunar-longitudes.csv</code>: flat machine-readable rows and locators.</li><li><code>lunar-longitudes.json</code>: identical structured rows.</li><li><code>metadata.json</code>: source SHA256, units, page ranges, method and limitations.</li><li><code>ambiguities-and-source-discrepancies.json</code>: unresolved discrepancy and header errors.</li><li><code>symmetry-check.json</code>: diagnostic against the source&#39;s printed verification rule.</li></ul><p>The Sanskrit mnemonic column is outside this numeric transcription&#39;s scope. Physical page numbers and row-on-page locators are one-based. The separate <code>pdf_page_index</code> is zero-based. Intermediate unnumbered day rows follow their printed anchors in order.</p><h2 id="findings-requiring-care" tabindex="-1">Findings requiring care <a class="header-anchor" href="#findings-requiring-care" aria-label="Permalink to &quot;Findings requiring care&quot;">​</a></h2><ol><li>Day 100, physical 165 / printed 128 / body row 21 reads <strong>8r1deg17min</strong>.</li><li>Day 148, physical 167 / printed 130 / body row 16 reads <strong>4r26deg17min</strong>.</li><li>These sum modulo 360 degrees to <strong>0r27deg34min</strong>, ten arcminutes below the printed page 134 verification target <strong>0r27deg44min</strong>.</li><li>Both minute cells visibly read 17; no corrected value is assigned.</li><li>Physical 170&#39;s running header says 208-232, but its 27 body rows span 208-234.</li><li>Physical 171&#39;s header says 233-248, but its 14 body rows explicitly begin 235.</li></ol><p>There are no remaining visually unreadable numeric cells in this reading. The source-authority discrepancy above remains unresolved. An initial low-resolution reading of day16&#39;s minutes as 16 was rejected after 250dpi inspection: the source visibly reads15; the final artifacts use15. Faint cells in rows 142,148 and155 were checked at 300 dpi.</p><h2 id="validation-and-limits" tabindex="-1">Validation and limits <a class="header-anchor" href="#validation-and-limits" aria-label="Permalink to &quot;Validation and limits&quot;">​</a></h2><p>All 248 sequential day indices are present exactly once. All numeric cells satisfy their column ranges. The book&#39;s complement relation passes all pairs except 100/148; this arithmetic diagnostic never supplies or silently corrects a cell. Day 124 is 6r13deg52min and day 248 is 0r27deg44min, consistent with the printed midpoint statement on page 134. Days 153 and154 agree with root&#39;s separate readings:7r7deg36min and7r21deg48min.</p><p>This is a single-transcriber draft, not an independently certified table. No epoch, ahargana, interpolation, time-of-day or engine model is implemented. It does not validate the current nine-offset engine. Publication of this transcription changes no engine or calculation behavior.</p><p>Next evidence steps are independent double-entry transcription, checking an alternate edition or errata for 100/148, and separately reconstructing the source&#39;s epoch/argument rules before any proposed model comparison.</p><h2 id="root-spot-review-—-2026-09-21" tabindex="-1">Root spot review — 2026-09-21 <a class="header-anchor" href="#root-spot-review-—-2026-09-21" aria-label="Permalink to &quot;Root spot review — 2026-09-21&quot;">​</a></h2><p>A separate visual spot review of complete physical pages 165 and 167, plus the higher-resolution crops, confirmed the day100 and day148 readings and their row locators. Both minute cells read17; the ten-arcminute inconsistency remains. This checks the flagged pair only, not independent double-entry of all248 rows.</p>',14)])])}const g=i(t,[["render",s]]);export{u as __pageData,g as default};
